// networkBytes normalizes API defaults and policy type order for comparisons.
// Object keys use a stable order. The hash contains no credential and does not
// replace ownership or admission checks.
func networkBytes(spec networkSpec) ([]byte, error) {
	spec.PolicyTypes = nil
	data, err := json.Marshal(spec)
	if err != nil {
		return nil, err
	}
	var canonical map[string]any
	if err = json.Unmarshal(data, &canonical); err != nil {
		return nil, err
	}
	return json.Marshal(canonical)
}
func networkHash(data []byte) string { sum := sha256.Sum256(data); return hex.EncodeToString(sum[:]) }

// requireNetwork verifies the complete declared policy before access is granted.
// It does not prove that the cluster network plugin has applied the policy.
// Ensure can update an intact owned policy to the current declaration. It
// returns ErrPending after a write so that the caller observes the result again.
// RequireNamespace is read-only. Foreign or changed stored content is rejected.
func (a *Allocator) requireNetwork(ctx context.Context, p profile, name string, owner kube.Owner, create bool) error {
	collection := "/apis/networking.k8s.io/v1/namespaces/" + name + "/networkpolicies"
	current, code, err := a.client.Request(ctx, http.MethodGet, collection+"/stego-allocation", nil)
	if err != nil {
		return err
	}
	if code == http.StatusNotFound {
		if !create {
			return ErrPending
		}
		meta := metadata("stego-allocation", owner)
		meta["namespace"] = name
		encoded, err := networkBytes(a.networkSpec(p, name))
		if err != nil {
			return err
		}
		meta["annotations"] = kube.Object{networkHashAnnotation: networkHash(encoded)}
		desired := kube.Object{"apiVersion": "networking.k8s.io/v1", "kind": "NetworkPolicy", "metadata": meta, "spec": a.networkSpec(p, name)}
		if _, _, err = a.client.Request(ctx, http.MethodPost, collection, desired); err != nil {
			return err
		}
		current, code, err = a.client.Request(ctx, http.MethodGet, collection+"/stego-allocation", nil)
		if err != nil {
			return err
		}
		if code == http.StatusNotFound {
			return ErrPending
		}
	}
	// Read all policy names. A label selector could hide a policy that permits traffic.
	page, status, err := a.client.Request(ctx, http.MethodGet, collection+"?limit=2", nil)
	if err != nil {
		return err
	}
	entries, ok := kube.Nested(page, "items").([]any)
	if status != http.StatusOK || !ok || len(entries) != 1 || kube.String(page, "metadata", "resourceVersion") == "" || kube.String(page, "metadata", "continue") != "" {
		return errors.New("allocation network policy snapshot is incomplete or has an unexpected policy")
	}
	observed, ok := entries[0].(map[string]any)
	if !ok || kube.String(observed, "metadata", "name") != "stego-allocation" || kube.String(observed, "metadata", "uid") != kube.String(current, "metadata", "uid") || kube.String(observed, "metadata", "resourceVersion") != kube.String(current, "metadata", "resourceVersion") {
		return errors.New("allocation network policy changed during observation")
	}
	current = kube.Object(observed)
	if !owner.Matches(current) || kube.String(current, "metadata", "name") != "stego-allocation" || kube.String(current, "metadata", "namespace") != name || kube.String(current, "metadata", "uid") == "" || kube.String(current, "metadata", "resourceVersion") == "" || kube.String(current, "metadata", "deletionTimestamp") != "" {
		return errors.New("allocation network policy is not owned and active")
	}
	var spec networkSpec
	data, err := json.Marshal(current["spec"])
	if err != nil {
		return errors.New("invalid allocation network policy")
	}
	decoder := json.NewDecoder(bytes.NewReader(data))
	decoder.DisallowUnknownFields()
	if err = decoder.Decode(&spec); err != nil || spec.PodSelector == nil || len(spec.PodSelector.MatchLabels) != 0 || len(spec.PodSelector.MatchExpressions) != 0 || len(spec.PolicyTypes) != 2 {
		return errors.New("invalid allocation network policy shape")
	}
	if !(spec.PolicyTypes[0] == "Ingress" && spec.PolicyTypes[1] == "Egress" || spec.PolicyTypes[0] == "Egress" && spec.PolicyTypes[1] == "Ingress") {
		return errors.New("allocation network policy must restrict both directions")
	}
	expected := a.networkSpec(p, name)
	actualJSON, err := networkBytes(spec)
	if err != nil {
		return err
	}
	expectedJSON, err := networkBytes(expected)
	if err != nil {
		return err
	}
	storedHash := kube.Nested(current, "metadata", "annotations", networkHashAnnotation)
	intact := storedHash == networkHash(actualJSON)
	if storedHash != nil && !intact {
		return errors.New("allocation network policy content differs from its recorded hash")
	}
	matches := bytes.Equal(actualJSON, expectedJSON)
	if !matches && (!create || !intact) {
		return errors.New("allocation network policy differs from its declared peers")
	}
	if create && (!matches || !intact) {
		// A legacy policy without a hash can be sealed only when it already matches
		// the current declaration. No changed policy is adopted through this path.
		patchSpec := kube.Object{"podSelector": kube.Object{"matchLabels": nil, "matchExpressions": nil}, "policyTypes": []string{"Ingress", "Egress"}, "ingress": nil, "egress": nil}
		if len(expected.Ingress) > 0 {
			patchSpec["ingress"] = expected.Ingress
		}
		if len(expected.Egress) > 0 {
			patchSpec["egress"] = expected.Egress
		}
		patch := kube.Object{"metadata": kube.Object{"uid": kube.String(current, "metadata", "uid"), "resourceVersion": kube.String(current, "metadata", "resourceVersion"), "annotations": kube.Object{networkHashAnnotation: networkHash(expectedJSON)}}, "spec": patchSpec}
		if _, _, err = a.client.Request(ctx, http.MethodPatch, collection+"/stego-allocation", patch); err != nil {
			return err
		}
		return ErrPending
	}

	return nil
}

// Delete removes cluster bindings first. It returns true only after all owned
// resources are absent. The caller must keep deleted application records until
// this method returns true. An absent namespace does not skip binding cleanup.
func (a *Allocator) Delete(ctx context.Context, profileName, name, ownerID string) (bool, error) {
	_, owner, err := a.request(profileName, name, ownerID)
	if err != nil {
		return false, err
	}
	// Read the namespace first so that a foreign owner cannot trigger any write.
	current, code, err := a.client.Request(ctx, http.MethodGet, "/api/v1/namespaces/"+name, nil)
	if err != nil {
		return false, err
	}
	if code != http.StatusNotFound && !owner.Matches(current) {
		return false, errors.New("namespace has a different owner")
	}
	ready := true
	collection := "/apis/rbac.authorization.k8s.io/v1/clusterrolebindings"
	bindings, err := a.bindings(ctx, collection, name, owner)
	if err != nil {
		return false, err
	}
	for _, old := range bindings {
		err := a.removeBinding(ctx, collection, old)
		if errors.Is(err, ErrPending) {
			ready = false
		} else if err != nil {
			return false, err
		}
	}
	if !ready {
		return false, nil
	}
	return a.client.DeleteOwned(ctx, "/api/v1/namespaces/"+name, owner)
}

// sealIdentity copies only declared public fields from an immutable record.
// Values on the Namespace can be set once. Loss of the source record cannot
// remove those values. Consumers must observe the seal before they use keys.
func (a *Allocator) sealIdentity(ctx context.Context, p profile, name string, owner kube.Owner) error {
	if p.IdentityConfigMap == "" {
		return nil
	}
	record, code, err := a.client.Request(ctx, http.MethodGet, "/api/v1/namespaces/"+name+"/configmaps/"+p.IdentityConfigMap, nil)
	if err != nil {
		return err
	}
	if code == 404 {
		return nil
	}
	if !owner.Matches(record) || record["immutable"] != true || kube.String(record, "metadata", "uid") == "" || kube.String(record, "metadata", "resourceVersion") == "" || kube.String(record, "metadata", "deletionTimestamp") != "" {
		return errors.New("namespace identity record is not owned and immutable")
	}
	fields := map[string]kube.Object{"labels": {}, "annotations": {}}
	for _, group := range []struct {
		name   string
		fields []identityField
	}{{"labels", p.IdentityLabels}, {"annotations", p.IdentityAnnotations}} {
		for _, field := range group.fields {
			value := kube.String(record, "data", field.Field)
			if len(value) == 0 || len(value) > 256 {
				return errors.New("invalid namespace identity value")
			}
			if group.name == "labels" && !ownerValue.MatchString(value) {
				return errors.New("invalid namespace identity label")
			}
			for _, c := range value {
				if c < 32 || c > 126 {
					return errors.New("namespace identity requires printable ASCII")
				}
			}
			fields[group.name][field.Key] = value
		}
	}
	current, code, err := a.client.Request(ctx, http.MethodGet, "/api/v1/namespaces/"+name, nil)
	if err != nil {
		return err
	}
	if code == 404 {
		return ErrPending
	}
	if !owner.Matches(current) || kube.String(current, "metadata", "uid") == "" || kube.String(current, "metadata", "resourceVersion") == "" || kube.String(current, "metadata", "deletionTimestamp") != "" {
		return errors.New("namespace identity target is not owned and active")
	}
	changes := kube.Object{"uid": kube.String(current, "metadata", "uid"), "resourceVersion": kube.String(current, "metadata", "resourceVersion")}
	missing := false
	for group, values := range fields {
		if len(values) == 0 {
			continue
		}
		for key, value := range values {
			old := kube.Nested(current, "metadata", group, key)
			if old != nil && old != value {
				return errors.New("namespace identity differs from its seal")
			}
			missing = missing || old == nil
		}
		changes[group] = values
	}
	if !missing {
		return nil
	}
	_, _, err = a.client.Request(ctx, http.MethodPatch, "/api/v1/namespaces/"+name, kube.Object{"metadata": changes})
	return err
}

// RequireNamespace checks allocation identity without creating or changing it.
// A resource worker needs read-only Namespace access. An isolated profile also
// needs get access to the named stego-allocation NetworkPolicy and list access
// to all NetworkPolicies in that namespace.
func (a *Allocator) RequireNamespace(ctx context.Context, profileName, name, ownerID string) error {
	if _, err := a.NamespaceUID(ctx, profileName, name, ownerID); err != nil {
		return err
	}
	p, owner, err := a.request(profileName, name, ownerID)
	if err != nil {
		return err
	}
	if p.NetworkIsolation {
		return a.requireNetwork(ctx, p, name, owner, false)
	}
	return nil
}

// NamespaceUID returns the identity of the verified, live allocation. It does
// not prove that every role binding is ready or that a worker has Pod access.
func (a *Allocator) NamespaceUID(ctx context.Context, profileName, name, ownerID string) (string, error) {
	_, owner, err := a.request(profileName, name, ownerID)
	if err != nil {
		return "", err
	}
	current, code, err := a.client.Request(ctx, http.MethodGet, "/api/v1/namespaces/"+name, nil)
	if err != nil {
		return "", err
	}
	if code == 404 {
		return "", ErrPending
	}
	if !owner.Matches(current) || kube.String(current, "metadata", "uid") == "" || kube.String(current, "metadata", "resourceVersion") == "" {
		return "", errors.New("namespace allocation has a different identity")
	}
	if kube.String(current, "metadata", "deletionTimestamp") != "" {
		return "", ErrPending
	}
	return kube.String(current, "metadata", "uid"), nil
}

// NamespaceGone observes cleanup without performing it. A foreign namespace
// with the same name is an error, not evidence that cleanup has completed.
func (a *Allocator) NamespaceGone(ctx context.Context, profileName, name, ownerID string) (bool, error) {
	_, owner, err := a.request(profileName, name, ownerID)
	if err != nil {
		return false, err
	}
	current, code, err := a.client.Request(ctx, http.MethodGet, "/api/v1/namespaces/"+name, nil)
	if err != nil {
		return false, err
	}
	if code == 404 {
		return true, nil
	}
	if !owner.Matches(current) || kube.String(current, "metadata", "uid") == "" || kube.String(current, "metadata", "resourceVersion") == "" {
		return false, errors.New("namespace allocation has a different identity")
	}
	return false, nil
}
